"""The typed schemas in workflow/schemas.py match the workflow and what the engine gives ADK (generated by adk_v2/6.0.0)."""

from typing import Any

import pytest
from pydantic import BaseModel

from retail_kyc_onboarding._engine.engine.schemas import decode_open_fields, fields_to_model
from retail_kyc_onboarding._engine.factories.api import HttpApiFactory
from retail_kyc_onboarding.workflow import WORKFLOW, schemas


def _structured(node: Any) -> Any:
    return node.config.get("structured_output") or {}


STRUCTURED = {n.id: _structured(n) for n in WORKFLOW.graph.nodes if _structured(n).get("enabled")}


def shape(model: type[BaseModel]) -> dict[str, Any]:
    """Field types and the required set of a model's JSON schema, ignoring titles and descriptions."""
    js = model.model_json_schema()
    props = {k: {kk: vv for kk, vv in v.items() if kk not in ("title", "description")} for k, v in js["properties"].items()}
    return {"properties": props, "required": sorted(js.get("required", []))}


def test_every_structured_step_has_an_output_model():
    """One model per step with a structured output, and no other."""
    assert set(schemas.OUTPUTS) == set(STRUCTURED)


@pytest.mark.parametrize("node_id", sorted(STRUCTURED))
def test_the_output_model_is_the_schema_adk_validates(node_id: str):
    """The static model has the fields of the output_schema the adapter hands to the step's LlmAgent, with the same types,
    except that the model is asked for an array or object as JSON text (decoded before it reaches the variables)."""
    fields = STRUCTURED[node_id]["output_schema"]
    static, wire = shape(schemas.OUTPUTS[node_id]), shape(fields_to_model(node_id, fields))
    assert static["required"] == wire["required"]
    assert set(static["properties"]) == set(wire["properties"])
    for name, spec in fields.items():
        if spec in ("array", "object"):
            assert static["properties"][name]["type"] == spec and wire["properties"][name]["type"] == "string"
        else:
            assert static["properties"][name] == wire["properties"][name]


def test_an_array_answer_reaches_the_variables_as_a_list():
    """OpenAI strict output has no open arrays: the model answers JSON text, which is decoded back to the declared type."""
    model = fields_to_model("step", {"reasons": "array", "summary": "string"})
    assert model.model_json_schema()["properties"]["reasons"]["type"] == "string"
    answer = model.model_validate({"reasons": '["no record"]', "summary": "[not json"}).model_dump()
    decoded = decode_open_fields({"reasons": "array", "summary": "string"}, answer)
    assert decoded == {"reasons": ["no record"], "summary": "[not json"}


@pytest.mark.parametrize("tool_id", sorted(WORKFLOW.tools))
def test_the_tool_args_model_is_the_declaration_the_model_sees(tool_id: str):
    """The static model has the same argument names, types, descriptions and required set as the tool's function declaration."""
    declared = HttpApiFactory().build(WORKFLOW.tools[tool_id]).json_schema()
    js = schemas.TOOL_ARGS[tool_id].model_json_schema()
    assert {k: (v["type"], v.get("description", "")) for k, v in js["properties"].items()} == {
        k: (v["type"], v["description"]) for k, v in declared["properties"].items()
    }
    assert sorted(js.get("required", [])) == sorted(declared["required"])


def test_a_tool_given_to_a_model_keeps_its_whole_json_schema():
    """ADK declares the tool with the handle's JSON schema as it is, so a nested array keeps its item type."""
    from retail_kyc_onboarding._engine.runtime.adk_tools import KayaAdkTool

    handle = HttpApiFactory().build(WORKFLOW.tools["retail_kyc_account_creation"])
    nested = {"type": "object", "properties": {"tags": {"type": "array", "items": {"type": "string"}}}, "required": ["tags"]}
    handle.json_schema = lambda: nested  # type: ignore[method-assign]
    declaration = KayaAdkTool(handle, engine=None, unit=None, node_id="n")._get_declaration()
    assert declaration.parameters_json_schema == nested and declaration.parameters is None


def test_the_workflow_state_covers_every_variable():
    """WorkflowState has one field per workflow variable, addressed by the variable's own name."""
    aliases = {f.alias for f in schemas.WorkflowState.model_fields.values()}
    assert aliases == {v.name for v in WORKFLOW.graph.variables}
    state = schemas.WorkflowState.model_validate({"kyc_risk_agent.kyc_risk": "LOW"})
    assert state.kyc_risk_agent_kyc_risk == "LOW"


def test_a_payload_is_validated():
    """A wrong payload fails validation with the field named."""
    with pytest.raises(ValueError, match="id_number"):
        schemas.RetailKycIdRegistryLookupArgs.model_validate({})
